import{_ as e,o as t,c as o,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"腾讯Agent开发岗：真正的核心是工程质量，不是调Prompt","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/career-observation/agent-development-engineering-core.md","filePath":"topics/career-observation/agent-development-engineering-core.md"}'),i={name:"topics/career-observation/agent-development-engineering-core.md"};function n(l,a,s,h,u,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="腾讯agent开发岗-真正的核心是工程质量-不是调prompt" tabindex="-1">腾讯Agent开发岗：真正的核心是工程质量，不是调Prompt <a class="header-anchor" href="#腾讯agent开发岗-真正的核心是工程质量-不是调prompt" aria-label="Permalink to &quot;腾讯Agent开发岗：真正的核心是工程质量，不是调Prompt&quot;">​</a></h1><blockquote><p>来源：腾讯 Agent 开发岗亲历拆解（2026-08） 核心命题：<strong>Agent 开发的核心挑战不是模型与 Prompt 调优，而是围绕工程质量展开的完整工程能力。岗位本质是招&quot;独当一面&quot;的工程师。</strong></p></blockquote><hr><h2 id="一、认知刷新-agent-开发的真实工作" tabindex="-1">一、认知刷新：Agent 开发的真实工作 <a class="header-anchor" href="#一、认知刷新-agent-开发的真实工作" aria-label="Permalink to &quot;一、认知刷新：Agent 开发的真实工作&quot;">​</a></h2><h3 id="外界误判-vs-实际" tabindex="-1">外界误判 vs 实际 <a class="header-anchor" href="#外界误判-vs-实际" aria-label="Permalink to &quot;外界误判 vs 实际&quot;">​</a></h3><ul><li><strong>误判</strong>：Agent 开发 = 跟模型 &amp; 复杂 Prompt 打交道</li><li><strong>实际</strong>：大部分时间在处理<strong>工程化问题</strong>，确保系统稳定可靠</li></ul><h3 id="解决真实问题-以排查线上故障为例" tabindex="-1">解决真实问题（以排查线上故障为例） <a class="header-anchor" href="#解决真实问题-以排查线上故障为例" aria-label="Permalink to &quot;解决真实问题（以排查线上故障为例）&quot;">​</a></h3><p>工作流程远不止&quot;修代码&quot;，而是完整链路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题诊断 → 根因分析 → 方案设计 → 性能评估 → 上线验证 → 文档沉淀</span></span></code></pre></div><hr><h2 id="二、四大强度要求" tabindex="-1">二、四大强度要求 <a class="header-anchor" href="#二、四大强度要求" aria-label="Permalink to &quot;二、四大强度要求&quot;">​</a></h2><h3 id="_1-代码能力-生产级代码" tabindex="-1">1. 代码能力：生产级代码 <a class="header-anchor" href="#_1-代码能力-生产级代码" aria-label="Permalink to &quot;1. 代码能力：生产级代码&quot;">​</a></h3><ul><li>不只是&quot;会用 Python&quot;，而是写<strong>考虑周全、健壮</strong>的代码</li><li>三要素：<strong>异常处理、可扩展性、可读性</strong></li><li>实践案例：一个 Tool 调用要处理—— <ul><li>API 超时</li><li>返回格式异常</li><li>数据为空</li><li>并发限流</li><li>每种情况配<strong>独立回退策略</strong></li></ul></li></ul><h3 id="_2-成本意识-算得明白" tabindex="-1">2. 成本意识：算得明白 <a class="header-anchor" href="#_2-成本意识-算得明白" aria-label="Permalink to &quot;2. 成本意识：算得明白&quot;">​</a></h3><ul><li>所有方案必须<strong>成本核算</strong>，不能只关心&quot;能不能跑通&quot;</li><li>要能说清：调用次数、Token 消耗、高峰期 QPS</li><li>实践：内部工具不控制 Token，<strong>每月几十万开销很常见</strong></li><li>成本控制 = 规模化应用的基础</li></ul><h3 id="_3-效果验证-用数据证明-prompt-有效性" tabindex="-1">3. 效果验证：用数据证明 Prompt 有效性 <a class="header-anchor" href="#_3-效果验证-用数据证明-prompt-有效性" aria-label="Permalink to &quot;3. 效果验证：用数据证明 Prompt 有效性&quot;">​</a></h3><ul><li>不能凭感觉调 Prompt，必须<strong>用数据证明优越性</strong></li><li>建立<strong>工程化评测体系</strong>： <ul><li>评测集</li><li>量化对比：正确率 / 拒识率 / 平均回复时长</li></ul></li></ul><h3 id="_4-上线流程-完整发布链路" tabindex="-1">4. 上线流程：完整发布链路 <a class="header-anchor" href="#_4-上线流程-完整发布链路" aria-label="Permalink to &quot;4. 上线流程：完整发布链路&quot;">​</a></h3><ul><li>上线不是结束，是一套严谨流程的开始：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>代码Review → 安全扫描 → 压测 → 灰度发布 → 监控告警配置 → 线上观察期</span></span></code></pre></div><ul><li><strong>每个环节都要通过审核</strong></li></ul><hr><h2 id="三、岗位本质-招聘-独当一面-的工程师" tabindex="-1">三、岗位本质：招聘&quot;独当一面&quot;的工程师 <a class="header-anchor" href="#三、岗位本质-招聘-独当一面-的工程师" aria-label="Permalink to &quot;三、岗位本质：招聘&quot;独当一面&quot;的工程师&quot;">​</a></h2><h3 id="独当一面-的定义" tabindex="-1">&quot;独当一面&quot;的定义 <a class="header-anchor" href="#独当一面-的定义" aria-label="Permalink to &quot;&quot;独当一面&quot;的定义&quot;">​</a></h3><p>从需求理解 → 方案设计 → 代码实现 → 上线验证，能对<strong>产品全生命周期负责</strong>；出问题时能<strong>独立排查、修复、复盘</strong>。</p><h3 id="经验优先级" tabindex="-1">经验优先级 <a class="header-anchor" href="#经验优先级" aria-label="Permalink to &quot;经验优先级&quot;">​</a></h3><ul><li><strong>有后端开发经验</strong>的候选人学新技术栈相对容易 → 更受青睐</li><li>公司要的是<strong>有工程经验的人才</strong>，而非只有框架使用经验的人</li></ul><hr><h2 id="四、跨主题关联" tabindex="-1">四、跨主题关联 <a class="header-anchor" href="#四、跨主题关联" aria-label="Permalink to &quot;四、跨主题关联&quot;">​</a></h2><h3 id="_1-天轴困局-工程重构逻辑" tabindex="-1">1. 天轴困局（工程重构逻辑） <a class="header-anchor" href="#_1-天轴困局-工程重构逻辑" aria-label="Permalink to &quot;1. 天轴困局（工程重构逻辑）&quot;">​</a></h3><p>&quot;Agent开发=工程质量而非AI&quot;与&quot;天轴困局&quot;（别外挂、要重构）<strong>同源</strong>——嘴上用 AI 不构成能力，把工程质量做到位才是真能力。工程化就是用&quot;重构&quot;代替&quot;外挂&quot;。</p><p>→ <code>ai-system-architecture/gear-shaft-org-reinvention.md</code></p><h3 id="_2-ai时代职场悖论" tabindex="-1">2. AI时代职场悖论 <a class="header-anchor" href="#_2-ai时代职场悖论" aria-label="Permalink to &quot;2. AI时代职场悖论&quot;">​</a></h3><p>&quot;公司招独当一面的工程人才&quot;正是对&quot;AI时代低价值岗位被裁&quot;的回应：<strong>被 AI 替代的是&quot;只会外挂/只会跑框架&quot;的人，被重用的是&quot;能独立交付工程质量&quot;的人</strong>。</p><p>→ <code>career-observation/ai-workplace-paradox.md</code></p><h3 id="_3-反差能力" tabindex="-1">3. 反差能力 <a class="header-anchor" href="#_3-反差能力" aria-label="Permalink to &quot;3. 反差能力&quot;">​</a></h3><p>&quot;不在成为 AI 专家，而在找到 AI 替代不了的能力&quot;——工程质量（稳定性/成本/评测/上线全生命周期）正是 AI 难以完全替代的&quot;反差能力&quot;之一。</p><p>→ <code>career-observation/reverse-ability-ai-era.md</code></p><h3 id="_4-创业心法-复用到个人成长" tabindex="-1">4. 创业心法（复用到个人成长） <a class="header-anchor" href="#_4-创业心法-复用到个人成长" aria-label="Permalink to &quot;4. 创业心法（复用到个人成长）&quot;">​</a></h3><p>&quot;独当一面 = 全生命周期负责&quot;，与创业心法&quot;从卖产品到卖系统&quot;同构——<strong>个人价值从&quot;会单点&quot;升级到&quot;能闭环&quot;</strong>。</p><p>→ <code>entrepreneurship/index.md</code></p><hr><h2 id="五、一句话带走" tabindex="-1">五、一句话带走 <a class="header-anchor" href="#五、一句话带走" aria-label="Permalink to &quot;五、一句话带走&quot;">​</a></h2><p>Agent 开发 ≠ 玩 AI。<strong>能不能做出生产级、可控成本、可评测、可上线的 Agent</strong>，是区分&quot;会 AI&quot;和&quot;能交付&quot;的分水岭。腾讯要的不是会用 Agent 的人，是能造出可靠 Agent 的人。</p><hr><h2 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h2><p>Agent开发、工程质量、生产级代码、成本核算、Token消耗、评测体系、灰度发布、独当一面、后端经验、工程能力</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><p>ai-system-architecture/gear-shaft-org-reinvention · career-observation/ai-workplace-paradox · career-observation/reverse-ability-ai-era · entrepreneurship/index</p>',49)])])}const q=e(i,[["render",n]]);export{p as __pageData,q as default};
